//! Lock bytes are stable: every committed `test-fixtures/lock-golden/*/raeva.lock`
//! reads and writes back byte for byte, and a lockfile built through the
//! public API writes the committed `api-built/raeva.lock`.
//!
//! Regenerate `api-built/raeva.lock` deliberately with
//! `RAEVA_TEST_BLESS=1 cargo test -p rv-lock --test lock_bytes`. The
//! `raeva sync` goldens are regenerated by `raeva/tests/cli/lock_golden.rs`.

use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;

use rv_lock::{
    LockArtifact, LockEdge, LockModule, LockModulePackage, LockPlatform, Lockfile, Scope,
    SnapshotStamp, SupportPom,
};
use rv_maven_types::{ArtifactCoord, Gav};
use rv_test_support::{fixtures, golden};
use tempfile::TempDir;

fn golden_locks() -> Vec<PathBuf> {
    let root = fixtures::path("lock-golden");
    fixtures::sorted_child_names(&root, |path| path.join("raeva.lock").is_file())
        .into_iter()
        .map(|name| root.join(name).join("raeva.lock"))
        .collect()
}

fn write_to_string(lock: &Lockfile) -> String {
    let dir = TempDir::new().expect("temp dir");
    let path = dir.path().join("raeva.lock");
    lock.write_atomic(&path).expect("write lock");
    fs::read_to_string(path).expect("read written lock")
}

#[test]
fn every_golden_lock_round_trips_byte_for_byte() {
    let locks = golden_locks();
    assert!(
        !locks.is_empty(),
        "no golden locks under lock-golden/; lock_golden inventories the directories"
    );
    for path in locks {
        let committed = fs::read_to_string(&path)
            .expect("read golden lock")
            .replace("\r\n", "\n");
        let lock = Lockfile::read(&path)
            .unwrap_or_else(|err| panic!("{} does not read: {err}", path.display()));
        let written = write_to_string(&lock);
        assert!(
            written == committed,
            "{} changes on read and write (- committed, + written):\n{}",
            path.display(),
            golden::line_diff(&committed, &written)
        );
    }
}

fn coordinate(artifact: &str, version: &str, classifier: Option<&str>) -> ArtifactCoord {
    ArtifactCoord::new("org.golden", artifact, version, "jar", classifier)
}

fn artifact(
    coordinate: ArtifactCoord,
    repo_url: &str,
    checksums: Vec<rv_maven_types::Digest>,
) -> LockArtifact {
    let mut artifact = LockArtifact::new(coordinate, repo_url.to_string());
    artifact.checksums = checksums;
    artifact.pom_sha256 = Some(("b".repeat(64)).parse().unwrap());
    artifact
}

fn package(coordinate: ArtifactCoord, direct_scope: Option<Scope>) -> LockModulePackage {
    LockModulePackage::new(coordinate, direct_scope)
}

/// Two platforms of a two-module reactor, given out of canonical order so the
/// writer's sorting is part of what the golden pins.
fn api_built_lock() -> Lockfile {
    let sha256 =
        |c: char| rv_maven_types::Digest::parse("sha256", &c.to_string().repeat(64)).unwrap();
    let sha1 = |c: char| rv_maven_types::Digest::parse("sha1", &c.to_string().repeat(40)).unwrap();

    let mut snapshot = artifact(
        ArtifactCoord::new("org.golden", "snap", "1.0-SNAPSHOT", "jar", None),
        "./repository/",
        vec![sha256('c')],
    );
    snapshot.snapshot = SnapshotStamp::new("20240101.010101", 7);
    let artifacts = vec![
        snapshot,
        artifact(
            coordinate("lib", "1.0", Some("jdk11")),
            "https://repo.example/maven2/",
            vec![sha256('e'), sha1('f')],
        ),
        {
            let mut legacy = artifact(
                coordinate("legacy", "0.1", None),
                "https://repo.example/maven2/",
                vec![sha1('a')],
            );
            legacy.other_repo_urls = vec!["./repository/".to_string()];
            legacy
        },
    ];

    let mut system = package(coordinate("vendored", "0.9", None), Some(Scope::System));
    system.system_path = Some("lib/vendored-0.9.jar".to_string());
    system.system_sha256 = Some("5".repeat(64).parse().unwrap());
    let mut workspace = package(
        ArtifactCoord::new("org.golden.app", "api", "1.0", "jar", None),
        Some(Scope::Compile),
    );
    workspace.workspace_module = Some("api/pom.xml".to_string());
    let mut app = LockModule::new(
        "app/pom.xml".to_string(),
        Gav::new("org.golden.app", "app", "1.0"),
        "jar".to_string(),
    );
    app.packages = vec![
        system,
        package(
            coordinate("lib", "1.0", Some("jdk11")),
            Some(Scope::Compile),
        ),
        workspace,
        {
            let mut legacy = package(coordinate("legacy", "0.1", None), None);
            legacy.scope = Scope::Runtime;
            legacy
        },
        package(
            ArtifactCoord::new("org.golden", "snap", "1.0-SNAPSHOT", "jar", None),
            Some(Scope::Test),
        ),
    ];
    app.edges = vec![LockEdge::new(1, 3, Some(rv_lock::Scope::Runtime), false)];
    let api = LockModule::new(
        "api/pom.xml".to_string(),
        Gav::new("org.golden.app", "api", "1.0"),
        "jar".to_string(),
    );

    let platform = |name: &str| {
        let mut entry = LockPlatform::new(name.parse().expect("platform"), "d".repeat(64));
        entry.artifacts = artifacts.clone();
        entry.modules = vec![app.clone(), api.clone()];
        entry.set_model_inputs(
            &["release".to_string(), "linux".to_string()],
            &BTreeMap::from([
                ("app/pom.xml".to_string(), "1".repeat(64).parse().unwrap()),
                ("api/pom.xml".to_string(), "2".repeat(64).parse().unwrap()),
            ]),
        );
        entry
    };

    let mut lock = Lockfile::new();
    lock.config_hash = Some("9".repeat(64));
    lock.platforms = vec![platform("windows-x86_64"), platform("linux-x86_64")];
    lock.set_repo_ids(BTreeMap::from([
        (
            "https://repo.example/maven2/".to_string(),
            ["corp".into(), "corp-snapshots".into()].into(),
        ),
        ("./repository/".to_string(), ["fixture".into()].into()),
    ]))
    .expect("repo ids");
    for platform in &mut lock.platforms {
        platform.support_poms.insert(
            "org.golden:bom:1.0".to_string(),
            SupportPom::new(
                "https://repo.example/maven2/",
                "4".repeat(64).parse().unwrap(),
            ),
        );
    }
    lock
}

#[test]
fn api_built_lock_writes_the_golden_bytes() {
    let written = write_to_string(&api_built_lock());
    golden::assert_golden(
        &fixtures::path("lock-golden/api-built/raeva.lock"),
        &written,
    );
}
